#include <bits/stdc++.h>

using namespace std;

using ll = long long;

ll cuadrados(int s)
{
    if (s <= 0) return 1;
    return 1 + 2LL * s * (s + 1LL);
}

ll triangulo(int l)
{
    if (l < 0) return 0;
    return max(0LL, 1LL * l * l);
}

ll triangulo(int n, int i, int d)
{
    if (n < 0) return 0;
    i++;
    d++;
    d = min(d, n);
    i = min(i, n);

    return max(0LL,
               -1LL * n + 1LL * n * d + 1LL * n * i +
               (1LL * d + i - 1LL * d * d - 1LL * i * i) / 2);
}

ll cuadrados(int &s, int &x, int &y, int &n)
{
    return cuadrados(s)
         - triangulo(s - abs(n - y))
         - triangulo(s - y)
         - triangulo(s - x, y, n - y)
         - triangulo(s - abs(n - x), y, n - 1);
}

int main()
{
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, x, y;
    ll c;
    cin >> n >> x >> y >> c;

    x--;
    y--;
    n--;

    if (c <= 1) {
        cout << 0 << '\n';
        return 0;
    }

    int izq = 0;
    int der = 2 * (n + 1) + 1;

    while (izq != der) {
        int mid = izq + (der - izq + 1) / 2;

        if (cuadrados(mid, x, y, n) < c)
            izq = mid;
        else
            der = mid - 1;
    }

    cout << izq + 1 << '\n';
    return 0;
}

